flight_plan.header:
#include "autopilot.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
#include "modules/digital_cam/dc.h"
#include "modules/nav/nav_survey_poly_osam.h"
#include "modules/nav/nav_mission4_geofence.h"

/* Photo-number block per mapping area: shots in area k are k*1000 + 1, +2 ...
   dc_photo_nr is the number of the LAST shot and is incremented before
   sending, so setting it to k*1000 makes the first frame k*1000 + 1. */
#define MISSION1_PHOTO_BLOCK 1000

/* tan(half of the camera FOV ACROSS the flight line). The AI Camera is
   66 x 52.3 deg, mounted in the centre of the fuselage with the 66 deg axis
   ACROSS THE WINGS (user, 2026-09-15): 2 * 60 m * tan(33) = 77.9 m swath.
   If it turns out to be the other way round, use 0.49098f (tan 26.15 deg,
   58.9 m swath at 60 m) - more, closer lines. */
#define MISSION1_TAN_HALF_CROSS_FOV 0.64941f

/* Survey line angle parallel to the edge wp_a-wp_b, in the module's own
   convention (atan(dy/dx), degrees), so the lines follow the corners when
   they are dragged in the GCS. dx is nudged off zero like the module does. */
static inline float mission1_line_angle(uint8_t wp_a, uint8_t wp_b)
{
  float dx = waypoints[wp_b].x - waypoints[wp_a].x;
  float dy = waypoints[wp_b].y - waypoints[wp_a].y;
  if (signbit(fabs(dx) - 0.000001f)) { dx = 0.000001f; }
  return DegOfRad(atan(dy / dx));
}

/* Point on the edge a-b, pushed `m` metres away from (cx, cy), where the
   across-line coordinate x*nx + y*ny equals T. */
static inline void mission1_edge_at(uint8_t a, uint8_t b, float cx, float cy, float m,
    float nx, float ny, float T, float *px, float *py)
{
  float ax = waypoints[a].x, ay = waypoints[a].y;
  float bx = waypoints[b].x, by = waypoints[b].y;
  float dx = bx - ax, dy = by - ay;
  float len = sqrtf(dx * dx + dy * dy);
  if (signbit(len - 0.001f)) { len = 1.0f; }
  float ex = -dy / len, ey = dx / len;
  if (!signbit((cx - ax) * ex + (cy - ay) * ey)) { ex = -ex; ey = -ey; }
  ax += ex * m; ay += ey * m;
  bx += ex * m; by += ey * m;
  float ta = ax * nx + ay * ny;
  float den = bx * nx + by * ny - ta;
  if (signbit(fabs(den) - 0.001f)) { den = 0.001f; }
  float u = (T - ta) / den;
  *px = ax + u * (bx - ax);
  *py = ay + u * (by - ay);
}

/* Set up ONE PASS of an interleaved two-pass survey of the quadrilateral
   n0-n1 (north edge), s0-s1 (south edge), lines parallel to edge_a-edge_b.

   The area is split into the fewest lines no more than max_sweep apart that
   exactly fit its width W across the lines: N lines at (k + 0.5) * W / N, so
   both outer lines sit half a spacing from the side edges. Pass 1 flies the
   lines of the same parity as the outer line on the side nearest ref_wp,
   pass 2 the others.

   Each pass is a plain nav_survey_poly_osam run at spacing 2 * s over a
   scratch polygon (out_wp .. out_wp+3, consecutive):
     - sides exactly parallel to the lines, one spacing s beyond the pass's
       outer lines, so the module (first line half its sweep = s in from the
       entry side, then every 2 s until it would pass the far side) flies
       exactly this pass's lines;
     - north and south edges = the area's edges pushed `overrun` metres
       OUTWARD, so lines continue straight past the area and the turns happen
       outside it.
   Turns span 2 s, at least 2 * POLY_OSAM_MIN_RADIUS here, so the module
   flies half circles, never omega loops.

   Entry corner: pass 1 on ref_wp's side, pass 2 on the side nearest the
   aircraft (where pass 1 ended); north or south end nearest the aircraft.
   The module sweeps away from the entry corner's side and starts at its
   end. Returns the number of lines in the pass; 0 means none, in which case
   the survey is not set up and the Run block's stale sweep-back count moves
   straight on. */
static inline uint8_t mission1_pass_setup(uint8_t n0, uint8_t n1, uint8_t s0, uint8_t s1,
    uint8_t edge_a, uint8_t edge_b, uint8_t ref_wp, uint8_t pass,
    float max_sweep, float overrun, float alt, uint8_t out_wp)
{
  float angle = mission1_line_angle(edge_a, edge_b);
  float th = RadOfDeg(angle);
  float nx = -sinf(th), ny = cosf(th);
  uint8_t c[4] = {n0, n1, s0, s1};
  float lo = 0.0f, hi = 0.0f, cx = 0.0f, cy = 0.0f;
  uint8_t i;
  for (i = 0; i != 4; i++) {
    float t = waypoints[c[i]].x * nx + waypoints[c[i]].y * ny;
    if (i == 0) { lo = t; hi = t; }
    if (signbit(t - lo)) { lo = t; }
    if (!signbit(t - hi)) { hi = t; }
    cx += 0.25f * waypoints[c[i]].x;
    cy += 0.25f * waypoints[c[i]].y;
  }
  float width = hi - lo;
  if (signbit(max_sweep - 1.0f)) { max_sweep = 1.0f; }
  /* -0.001: a width of exactly k strips must give k lines, not k+1 */
  float nl = ceilf(width / max_sweep - 0.001f);
  if (signbit(nl - 1.0f)) { nl = 1.0f; }
  int N = (int)nl;
  float s = width / nl;

  float tref = waypoints[ref_wp].x * nx + waypoints[ref_wp].y * ny;
  bool ref_low = signbit(tref - 0.5f * (lo + hi));
  int k_ref = ref_low ? 0 : N - 1;
  int parity = (pass == 1) ? (k_ref % 2) : ((k_ref + 1) % 2);
  int kmin = parity;
  int kmax = (((N - 1) % 2) == parity) ? N - 1 : N - 2;
  if (signbit((float)(kmax - kmin))) { return 0; }

  float plo = lo + ((float)kmin + 0.5f) * s - s;
  float phi = lo + ((float)kmax + 0.5f) * s + s;
  float x[4], y[4];
  /* x + k, not the address-of form: a raw ampersand is not valid XML */
  mission1_edge_at(n0, n1, cx, cy, overrun, nx, ny, plo, x + 0, y + 0);
  mission1_edge_at(n0, n1, cx, cy, overrun, nx, ny, phi, x + 1, y + 1);
  mission1_edge_at(s0, s1, cx, cy, overrun, nx, ny, phi, x + 2, y + 2);
  mission1_edge_at(s0, s1, cx, cy, overrun, nx, ny, plo, x + 3, y + 3);

  float px = stateGetPositionEnu_f()[0].x;
  float py = stateGetPositionEnu_f()[0].y;
  bool entry_low = ref_low;
  if (pass != 1) { entry_low = signbit(px * nx + py * ny - 0.5f * (plo + phi)); }
  uint8_t cn = entry_low ? 0 : 1;   /* north corner on the entry side */
  uint8_t cs = entry_low ? 3 : 2;   /* south corner on the entry side */
  float dn = (x[cn] - px) * (x[cn] - px) + (y[cn] - py) * (y[cn] - py);
  float ds = (x[cs] - px) * (x[cs] - px) + (y[cs] - py) * (y[cs] - py);
  uint8_t first = signbit(dn - ds) ? cn : cs;

  /* rotate the cyclic order so the entry corner comes first */
  for (i = 0; i != 4; i++) {
    uint8_t j = (first + i) % 4;
    waypoints[out_wp + i].x = x[j];
    waypoints[out_wp + i].y = y[j];
    waypoints[out_wp + i].a = alt;
  }
  nav_survey_poly_osam_setup(out_wp, 4, 2.0f * s, angle);
  return (uint8_t)((kmax - kmin) / 2 + 1);
}

/* Shoot only with the wings near level, only within alt_tol of the survey
   altitude (no frames on the climb into Area 1), only while the GROUND
   TRACK runs along the survey lines (either direction, within
   max_course_err_deg of line_angle_deg - no frames on the transit to a
   pass's first line; ground track, not heading, so crabbing into a
   crosswind does not block the lines), and only inside the area being
   mapped (now AND `lookahead` seconds ahead along the ground track). Area
   corners are passed as waypoint ids because this header is emitted before
   the WP_ defines; n is up to 6, unused ids are ignored.

   Sets dc_autoshoot directly rather than dc_stop()/dc_distance(): those send
   DC_INFO on every call (20 Hz flood) and dc_distance() resets the last shot
   position. See mission2_shoot_in_zone() in mission2_strasbourg.xml.
   No raw angle brackets or ampersands anywhere in this header: they make
   the flight plan invalid XML (Xml_light_errors on build). */
static inline void mission1_shoot_in_area(float max_roll_deg, float lookahead,
    float alt_now, float alt_target, float alt_tol,
    float line_angle_deg, float max_course_err_deg, uint8_t n,
    uint8_t w0, uint8_t w1, uint8_t w2, uint8_t w3, uint8_t w4, uint8_t w5)
{
  uint8_t ids[6] = {w0, w1, w2, w3, w4, w5};
  float vx[6], vy[6];
  uint8_t i;
  for (i = 0; i != n; i++) {
    vx[i] = waypoints[ids[i]].x;
    vy[i] = waypoints[ids[i]].y;
  }
  /* Roll no longer gates shots: shoot at any bank angle. */
  (void)max_roll_deg;
  bool shoot = true;
  float x = stateGetPositionEnu_f()[0].x;
  float y = stateGetPositionEnu_f()[0].y;
  float ax = x + stateGetSpeedEnu_f()[0].x * lookahead;
  float ay = y + stateGetSpeedEnu_f()[0].y * lookahead;
  if (!mission4_in_poly(vx, vy, n, x, y)) { shoot = false; }
  if (!mission4_in_poly(vx, vy, n, ax, ay)) { shoot = false; }
  if (!signbit(fabs(alt_now - alt_target) - alt_tol)) { shoot = false; }
  float sx = stateGetSpeedEnu_f()[0].x;
  float sy = stateGetSpeedEnu_f()[0].y;
  float track_err = fmod(fabs(DegOfRad(atan2f(sy, sx)) - line_angle_deg), 180.0f);
  if (!signbit(track_err - 90.0f)) { track_err = 180.0f - track_err; }
  if (!signbit(track_err - max_course_err_deg)) { shoot = false; }
  if (shoot) {
    dc_autoshoot = DC_AUTOSHOOT_DISTANCE;
  } else {
    dc_autoshoot = DC_AUTOSHOOT_STOP;
  }
}
